vertex.source:
#version 300 es

// Vertex coordinates in object space for the render quad
in vec3 vertexPosition;

uniform float canvasWidth;
uniform float canvasHeight;

uniform vec3 cameraPosition;
uniform mat3 cameraRotation;

uniform bool isOrthographicProjection;
uniform float orthographicFOV;
uniform float perspectiveFOV;

out vec3 ray_origin;
out vec3 ray_dir;

void main() {
    float aspectRatio = canvasWidth/canvasHeight;
    vec3 origin_camSpace, dir_camSpace;
    if (isOrthographicProjection) {
        origin_camSpace = vec3(vertexPosition.x*orthographicFOV*aspectRatio,
                                vertexPosition.y*orthographicFOV,
                                0);
        dir_camSpace = vec3(0, 0, -1);
    }
    else { // perspective projection
        origin_camSpace = vec3(0);
        dir_camSpace = vec3(vertexPosition.x*aspectRatio,
                            vertexPosition.y,
                            -1.0/tan(radians(perspectiveFOV)));
    }
    ray_origin = cameraPosition + cameraRotation*origin_camSpace;
    ray_dir = normalize(cameraRotation*dir_camSpace);
    gl_Position = vec4(vertexPosition, 1.0);
}

fragment.source:
#version 300 es

/*
    Extension - Transparency

    Implemented transparency on one of the spheres. Spheres are placed in space
    to demonstrate the see-through and light-curving effects of the material.

    Raytracing Controls - 

    *   Raytracing depth: DEPTH macro (Ln 41)
        Since there is no recursion in GLSL, a binary heap was used to implement
        the ray tree. The misnamed DEPTH macro is actually the size of the heap.
        This meant that: DEPTH = 2 ^ (actual depth) - 1. With the default being 31, 
        the depth is 5. In the provided screenshot, depth was set to 6. This 
        affects whether we can see through the two transparent spheres.

    Scene Controls -

    *   Sphere count: NUM_SPHERE macro (Ln 42)
        Number of spheres. Sphere info located in "sphere" array in main.

    *   Sphere properties: Sphere struct (Ln 52)
        Sphere centre and radius set as before in Task 6a.

    *   Sphere material: Sphere struct (Ln 52)
        Colour is set through "sphere.colour". Transparency is set through 
        "sphere.transparent". Only 2 types of materials are available, as 
        reflection and pass-through coefficients are hard-coded.

    *   Light location: light vec3 variable (Ln 221) 
        Location of light within the scene.

    Material Controls -

    *   Refractive index: N2 macro (Ln 40)
        Refractive index of transparent material.
        With the default being 1.45, which imitates glass.
*/

#define N2 1.15
#define DEPTH 31
#define NUM_SPHERE 5

precision highp float;

in vec3 ray_origin;
in vec3 ray_dir;

out vec4 fragColor;


struct Sphere {
    vec3 centre;
    float radius;
    vec3 colour;

    bool transparent;
};

struct Plane {
    vec3 point;
    vec3 normal;
    vec3 colour;
};

struct Ray {
    // initialized
    vec3 origin;
    vec3 dir;
    bool in_sphere;
    float ratio;

    // calculated in-loop
    vec3 target;
    int item;

    // calculated last
    vec4 colour;
};

float intersect_sphere_entry(vec3 origin, vec3 dir, Sphere sphere) {
    vec3 p_0 = origin;
    vec3 d = normalize(dir);
    vec3 p_s = sphere.centre;
    vec3 del_p = p_0 - p_s;
    float r = sphere.radius;

    float det = 0.;
    det += dot(d, del_p) * dot(d, del_p);
    det -= dot(del_p, del_p);
    det += r * r;

    float mu = 0.;
    if (det < 0.) mu = -1.;
    else mu = - dot(d, del_p) - sqrt(det);

    return mu;
}

float intersect_sphere_exit(vec3 origin, vec3 dir, Sphere sphere) {
    vec3 p_0 = origin;
    vec3 d = normalize(dir);
    vec3 p_s = sphere.centre;
    vec3 del_p = p_0 - p_s;
    float r = sphere.radius;

    float det = 0.;
    det += dot(d, del_p) * dot(d, del_p);
    det -= dot(del_p, del_p);
    det += r * r;

    float mu = 0.;
    if (det < 0.) mu = -1.;
    else mu = - dot(d, del_p) + sqrt(det);

    return mu;
}

float intersect_plane(vec3 origin, vec3 dir, Plane plane) {
    vec3 p_0 = origin;
    vec3 d = normalize(dir);
    vec3 p_1 = plane.point;
    vec3 n = normalize(plane.normal);

    float mu = - dot((p_0 - p_1), n) / dot(d, n);
    return mu;
}

vec4 trace(vec3 intersection, vec3 dir, vec3 light, Sphere sphere) {
    vec3 n = normalize(intersection - sphere.centre);
    vec3 l = normalize(light - intersection);
    vec3 r = normalize(2. * dot(n, l) * n - l);
    vec3 v = -normalize(dir);

    float shininess = 20.;
    float atten = 1. / length(intersection - light);
    float I = 6. * atten;

    vec4 ambientCol = vec4(0, 0, 0, 1.);
    vec4 diffuseCol = 0.8 * clamp(I * max(0., dot(n, l)) * vec4(sphere.colour, 1.), 0., 1.);
    vec4 specularCol = clamp(I * pow(max(0.0, dot(r, v)), shininess) * vec4(sphere.colour, 1.0), 0., 1.);

    return clamp(ambientCol + diffuseCol + specularCol, 0., 1.);
}

bool is_obscured(vec3 origin, vec3 light, Sphere sphere) {
    return (intersect_sphere_entry(origin, normalize(light-origin), sphere) > 0.);
}

vec3 intersection(vec3 origin, vec3 dir, float dist) {
    return origin + normalize(dir) * dist;
}


// view always points toward intersection
// normal always points outwards
vec3 reflection_outside(vec3 view, vec3 normal) {
    vec3 v = -normalize(view);
    vec3 n = normalize(normal);
    return normalize(2. * dot(v, n) * n - v);
}

vec3 reflection_inside(vec3 view, vec3 normal) {
    vec3 v = -normalize(view);
    vec3 n = -normalize(normal);
    return normalize(2. * dot(v, n) * n - v);
}

vec3 transmission_entry(vec3 view, vec3 normal) {
    vec3 v = normalize(view);
    vec3 n = normalize(normal);
    float rn = 1. / N2;
    float det = sqrt(pow(dot(n, v), 2.) + pow(1./rn, 2.) - 1.);
    if (det >= 0.)  
        return normalize(rn * ((sqrt(det) - dot(n, v)) * n + v));
    else 
        return vec3(0., 0., 0.);
}

vec3 transmission_exit(vec3 view, vec3 normal) {
    vec3 v = normalize(view);
    vec3 n = -normalize(normal);
    float rn = N2 / 1.;
    float det = sqrt(pow(dot(n, v), 2.) + pow(1./rn, 2.) - 1.);

    if (det >= 0.) 
        return normalize(rn * ((sqrt(det) - dot(n, v)) * n + v));
    else 
        return vec3(0., 0., 0.);
}


void main() {
    // scene def start
    Sphere sphere[NUM_SPHERE];
    sphere[0].centre = vec3(-1.8, 1., -3.);
    sphere[0].radius = 1.5;
    sphere[0].colour = vec3(0.3, 0.7, 0.8);
    sphere[0].transparent = true;

    sphere[1].centre = vec3(0.5, 1.1, -.8);
    sphere[1].radius = 1.6;
    sphere[1].colour = vec3(0.8, 0.8, 0.8);
    sphere[1].transparent = true;

    sphere[2].centre = vec3(.6, .1, -3.);
    sphere[2].radius = .6;
    sphere[2].colour = vec3(0.8, 0.3, 0.3);
    sphere[2].transparent = false;

    sphere[3].centre = vec3(3.5, 2.5, -8);
    sphere[3].radius = 3.;
    sphere[3].colour = vec3(0.8, 0.8, 0.3);
    sphere[3].transparent = false;

    sphere[4].centre = vec3(3.5, .1, -1.);
    sphere[4].radius = .6;
    sphere[4].colour = vec3(0.8, 0.3, 0.8);
    sphere[4].transparent = true;

    Plane plane;
    plane.point = vec3(0., -0.5, 0.);
    plane.normal = vec3(0, 1.0, 0);
    plane.colour = vec3(1., 1., 1.);

    vec3 light = vec3(1., 4.5, -2.); 
    // scene def end


    // trace ray
    Ray heap[DEPTH];
    heap[0].origin = ray_origin;
    heap[0].dir = ray_dir;
    heap[0].in_sphere = false;
    heap[0].ratio = 1.; 

    for (int i = 0; i < DEPTH; ++i) {
        if (heap[i].ratio == 0.) {
            if (i*2+2 < DEPTH) {
                heap[i*2+1].ratio = 0.;
                heap[i*2+2].ratio = 0.;
            }
            continue;
        }

        float min_dist = -1.;
        float dist;
        vec3 next_origin;
        vec3 next_normal;
        int next_item;

        // check sphere
        for (int j = 0; j < NUM_SPHERE; ++j) {
            // if origin is in_sphere, we want to exit
            if (heap[i].in_sphere) dist = intersect_sphere_exit(heap[i].origin, heap[i].dir, sphere[j]);
            else dist = intersect_sphere_entry(heap[i].origin, heap[i].dir, sphere[j]);

            if ((dist >= 0.) && (min_dist < 0. || dist < min_dist)) {
                min_dist = dist;
                next_origin = intersection(heap[i].origin, heap[i].dir, min_dist);
                next_normal = normalize(next_origin - sphere[j].centre);
                next_origin -= next_normal * 0.00001;
                next_item = j;
            }
        }

        // check plane
        dist = intersect_plane(heap[i].origin, heap[i].dir, plane);
        if ((dist >= 0.) && (min_dist < 0. || dist < min_dist)) {
            min_dist = dist;
            next_origin = intersection(heap[i].origin, heap[i].dir, min_dist);
            next_normal = normalize(plane.normal);
            next_origin += next_normal * 0.00001;
            next_item = NUM_SPHERE;
        }

        // setup yourself
        if (min_dist < 0.) {
            heap[i].target = next_origin;
            heap[i].item = -1;
        } else {
            heap[i].target = next_origin;
            heap[i].item = next_item;
        }

        // setup children
        if (i*2+2 < DEPTH) {
            if (min_dist < 0.) {
                heap[i*2+1].ratio = 0.;
                heap[i*2+2].ratio = 0.;
            } else {
                if (next_item == 2 || !sphere[next_item].transparent) { // full reflection
                    heap[i*2+1].origin = next_origin;
                    if (heap[i].in_sphere) {
                        heap[i*2+1].in_sphere = true;
                        heap[i*2+1].dir = reflection_inside(heap[i].dir, next_normal);
                    } else {
                        heap[i*2+1].in_sphere = false;
                        heap[i*2+1].dir = reflection_outside(heap[i].dir, next_normal);
                    }
                    heap[i*2+1].ratio = .15;

                    heap[i*2+2].ratio = 0.;
                } else { // both
                    heap[i*2+1].origin = next_origin;
                    if (heap[i].in_sphere) {
                        heap[i*2+1].in_sphere = true;
                        heap[i*2+1].dir = reflection_inside(heap[i].dir, next_normal);
                    } else {
                        heap[i*2+1].in_sphere = false;
                        heap[i*2+1].dir = reflection_outside(heap[i].dir, next_normal);
                    }
                    heap[i*2+1].ratio = .1;

                    heap[i*2+2].origin = next_origin;
                    if (heap[i].in_sphere) {
                        heap[i*2+2].in_sphere = false;
                        heap[i*2+2].dir = transmission_exit(heap[i].dir, next_normal);
                    } else {
                        heap[i*2+2].in_sphere = true;
                        heap[i*2+2].dir = transmission_entry(heap[i].dir, next_normal);
                    }
                    heap[i*2+2].ratio = .9;
                }
            }
        }
    }

    // color
    for (int i = DEPTH-1; i >= 0; --i) {
        if (heap[i].ratio == 0.) {
            heap[i].colour = vec4(.0, .0, .0, 1.);
            continue;
        }

        vec4 local;
        if (0 <= heap[i].item && heap[i].item < NUM_SPHERE) {
            local = trace(heap[i].target, heap[i].dir, light, sphere[heap[i].item]);
        } else if (heap[i].item == NUM_SPHERE) {
            float forward = floor(heap[i].target.z);
            float lateral = floor(heap[i].target.x);
            if (mod(forward, 2.0) == 0. && mod(lateral, 2.0) == 0. || mod(forward, 2.0) == 1. && mod(lateral, 2.0) == 1.) {
                local = vec4(0., 0., 0., 1.) * 8. * (1. / length(light-heap[i].target));
            } else {
                local = vec4(.7, .7, .7, 1.) * 8. * (1. / length(light-heap[i].target));
            }
        } else {
            local = vec4(0., 0., 0., 1.);
        }

        float shadow = 1.;
        for (int j = 0; j < NUM_SPHERE; ++j) {
            if (sphere[j].transparent) {
                if (is_obscured(heap[i].target, light, sphere[j])) shadow -= 0.25;
            } else {
                if (is_obscured(heap[i].target, light, sphere[j])) shadow = 0.4;
            }
        }

        heap[i].colour = shadow * local;
        if (i*2+2 < DEPTH) {
            heap[i].colour += clamp(heap[i*2+1].ratio * heap[i*2+1].colour, 0., 1.);
            heap[i].colour += clamp(heap[i*2+2].ratio * heap[i*2+2].colour, 0., 1.);
        }

        heap[i].colour = clamp(heap[i].colour, 0., 1.);
    }

    fragColor = heap[0].colour;
}
